        print(r["ts"][11:23], "HTTP", r["method"], r["path"][-32:], r["status"], r["ms"], "sup", r.get("supplier_id"))
    else:
        e = r.get("event") or r.get("type") or r.get("kind")
        if e in ("attachment", "decision"):
