"""Is one session's traffic served one call at a time? And the reply/decision times of every session."""
import glob
import json
import statistics as st
import sys
from collections import defaultdict
from datetime import datetime

detail = set(sys.argv[1:])


def ts(s):
    return datetime.fromisoformat(s).timestamp()


single_post, multi_post, single_after, multi_after = [], [], [], []
overlap_stats = []
get_wait = defaultdict(list)
for run in sorted(glob.glob("agent/runs/*/")):
    try:
        http = [json.loads(x) for x in open(run + "http.jsonl")]
        ev = [json.loads(x) for x in open(run + "events.jsonl")]
    except FileNotFoundError:
        continue
    nsup = {}
    for e in ev:
        if e.get("kind") == "session_opened":
            nsup[e["session_id"]] = len(e.get("suppliers") or [])
    by = defaultdict(list)
    for h in http:
        if h.get("session_id") and h["status"] == 200:
            end = ts(h["ts"])
            by[h["session_id"]].append((end - h["ms"] / 1000, end, h))
    for e in ev:
        if e.get("kind") == "message_sent" and e.get("session_id") in nsup:
            (multi_after if nsup[e["session_id"]] > 1 else single_after).append(
                (e.get("seconds_after_reply") or 0, run.split("/")[2], e["session_id"], e.get("supplier_id"))
            )
    for sid, calls in by.items():
        n = nsup.get(sid)
        if n is None:
            continue
        posts = sorted([c for c in calls if c[2]["method"] == "POST" and c[2]["path"].endswith("/messages")], key=lambda c: c[1])
        for s, e, h in posts:
            (multi_post if n > 1 else single_post).append((e - s, run.split("/")[2], sid))
        if n > 1:
            # concurrency: how many message POSTs were in flight at once, and how many completed while another
            # one that had started earlier was still in flight (out of order = not FIFO)
            inflight = 0
            for i, (s, e, h) in enumerate(posts):
                inflight = max(inflight, sum(1 for s2, e2, _ in posts if s2 < e and e2 > s))
            # serial test: gaps between consecutive completions vs the latency of the later one
            gaps = [posts[i][1] - posts[i - 1][1] for i in range(1, len(posts))]
            overlap_stats.append((run.split("/")[2], sid, n, len(posts), inflight, round(min(gaps), 2) if gaps else None))
            if sid in detail:
                for s, e, h in sorted(calls, key=lambda c: c[1]):
                    print(f"{datetime.fromtimestamp(s).strftime('%H:%M:%S.%f')[:-4]} -> {datetime.fromtimestamp(e).strftime('%H:%M:%S.%f')[:-4]} "
                          f"{h['ms']/1000:7.2f}s {h['method']} {h['path'].split(sid)[-1]}")
        # GETs that overlapped a message POST of the same session vs those that did not
        for s, e, h in calls:
            if h["method"] != "GET":
                continue
            busy = any(ps < s and pe > s + 0.05 for ps, pe, _ in posts)
            get_wait[(n > 1, busy, h["endpoint"].split("/")[-1])].append(e - s)


def q(xs):
    xs = sorted(xs)
    return f"n={len(xs)} median={st.median(xs):.1f} p90={xs[int(.9*len(xs))-1]:.1f} max={xs[-1]:.1f} over60={sum(x>60 for x in xs)}"


print("POST /messages latency, single-supplier sessions:", q([x[0] for x in single_post]))
print("POST /messages latency, multi-supplier sessions: ", q([x[0] for x in multi_post]))
print("seconds_after_reply (ours), single:", q([x[0] for x in single_after]))
print("seconds_after_reply (ours), multi: ", q([x[0] for x in multi_after]))
print("single-supplier POSTs over 60 s:", [(round(a, 1), b, c) for a, b, c in single_post if a > 60])
print("single seconds_after_reply over 40:", [x for x in single_after if x[0] > 40])
print("multi seconds_after_reply over 40:", [x for x in multi_after if x[0] > 40])
print()
print("GET latency by (multi, a message POST of the session in flight, endpoint):")
for k, v in sorted(get_wait.items()):
    print("  ", k, q(v))
print()
print("multi sessions: run sid n_sup posts max_in_flight min_gap_between_completions")
for r in overlap_stats:
    if r[2] == 3 or "-v" in detail:
        print("  ", r)
allgaps = [r[5] for r in overlap_stats if r[5] is not None]
print("min completion gap over all multi sessions:", min(allgaps), "sessions:", len(overlap_stats))

